mapper.select:
select *
from simulation_progress
where progress_id =
#{progressId}
and member_id = #{memberId}

mapper.update:
update simulation_progress
set step_id = #{nextStepId}
where progress_id = #{progressId}
and member_id = #{memberId}
and
step_id = #{currentStepId}
and progress_status = 'IN_PROGRESS'

mapper.select:
SELECT EXISTS (
SELECT 1
FROM scenario_step current_step
JOIN scenario_step target_step
ON current_step.scenario_id = target_step.scenario_id
WHERE current_step.step_id = #{currentStepId}
AND target_step.step_id = #{targetStepId}
AND current_step.scenario_id = #{scenarioId}
AND current_step.step_order > 0
AND target_step.step_order > 0
AND target_step.step_order = current_step.step_order + 1
)
